import 'dart:convert';

import '../app_config.dart';
import '../wallets/crypto_currency/crypto_currency.dart';
import 'logger.dart';

/// Parsed parameters as a map, plus the values of the amount and label
/// parameters as lists: one per recipient for a Monero URI's `;` lists, else
/// a single value; null when the parameter is absent. From `_parseUri`, the
/// map also holds the scheme and address.
typedef _ParsedParams = ({
  Map<String, String> params,
  List<String>? amounts,
  List<String>? labels,
});

class AddressUtils {
  static final Set<String> recognizedParams = {
    'amount',
    'label',
    'message',
    'tx_amount', // For Monero/Wownero.
    'tx_payment_id',
    'recipient_name',
    'tx_description',
    'op_return', // For Rosen Bridge and other OP_RETURN protocols.
    'memo', // Stellar SEP-0007.
    'dt', // XRP destination tag.
    'destination_tag',
    // TODO [prio=med]: Add more recognized params for other coins.
  };

  static String condenseAddress(String address) {
    return '${address.substring(0, 5)}...${address.substring(address.length - 5)}';
  }

  /// Return only recognized parameters.
  static Map<String, String> _filterParams(Map<String, String> params) {
    return Map.fromEntries(
      params.entries.where(
        (entry) => recognizedParams.contains(entry.key.toLowerCase()),
      ),
    );
  }

  /// Parses a URI string into its components.
  static _ParsedParams _parseUri(String uri) {
    final Map<String, String> result = {};
    List<String>? amounts;
    List<String>? labels;
    try {
      final u = Uri.parse(uri);
      if (u.hasScheme) {
        result["scheme"] = u.scheme.toLowerCase();

        // Handle different URI formats.
        if (result["scheme"] == "bitcoin" ||
            result["scheme"] == "bitcoincash") {
          result["address"] = u.path;
        } else if (result["scheme"] == "monero") {
          // Monero addresses can contain '?' which Uri.parse interprets as query start.
          final addressEnd = uri.indexOf(
            '?',
            7,
          ); // 7 is the length of "monero:".
          if (addressEnd != -1) {
            result["address"] = uri.substring(7, addressEnd);
          } else {
            result["address"] = uri.substring(7);
          }
        } else {
          // Default case, treat path as address.
          result["address"] = u.path;
        }

        // Parse query parameters.
        final Map<String, List<String>> values;
        if (result["scheme"] == "monero") {
          // Monero URIs may list a value per recipient, separated by `;`.
          // Split the still percent-encoded query before decoding each value,
          // so that a `%3B` within a name is a `;` in it, not a separator.
          values = _splitQueryLists(u.query);
        } else {
          values = u.queryParameters.map(
            (key, value) => MapEntry(key, [value]),
          );
        }
        final parsed = _parseQueryParameters(values);
        result.addAll(parsed.params);
        amounts = parsed.amounts;
        labels = parsed.labels;

        // Handle Monero-specific fragment (tx_description).
        if (u.fragment.isNotEmpty && result["scheme"] == "monero") {
          result["tx_description"] = Uri.decodeComponent(u.fragment);
        }
      }
    } on FormatException {
      rethrow;
    } catch (e, s) {
      Logging.instance.d(
        "Exception caught in parseUri($uri): $e",
        error: e,
        stackTrace: s,
      );
    }
    return (params: result, amounts: amounts, labels: labels);
  }

  /// Splits a still percent-encoded [query] (as `Uri.query` returns it) into
  /// its parameters, each with its `;` separated values decoded one by one.
  static Map<String, List<String>> _splitQueryLists(String query) {
    final Map<String, List<String>> result = {};
    for (final pair in query.split('&')) {
      final split = pair.indexOf('=');
      final key = split < 0 ? pair : pair.substring(0, split);
      if (key.isEmpty) {
        continue;
      }
      final value = split < 0 ? '' : pair.substring(split + 1);
      result[Uri.decodeQueryComponent(key)] = [
        for (final e in value.split(';')) Uri.decodeQueryComponent(e),
      ];
    }
    return result;
  }

  /// Helper method to parse and normalize query parameters, each given as its
  /// list of values: one per recipient for a Monero URI's lists, else one.
  static _ParsedParams _parseQueryParameters(Map<String, List<String>> params) {
    final Map<String, String> result = {};
    List<String>? amounts;
    List<String>? labels;
    for (final MapEntry(:key, value: values) in params.entries) {
      final lowerKey = key.toLowerCase();
      final value = values.join(';');
      if (recognizedParams.contains(lowerKey)) {
        switch (lowerKey) {
          case 'amount':
          case 'tx_amount':
            amounts = [
              for (final e in values)
                _normalizeAmount(e) ??
                    (throw FormatException(
                      "Invalid payment URI amount: $value",
                    )),
            ];
            result['amount'] = amounts.join(';');
            break;
          case 'label':
          case 'recipient_name':
            labels = values;
            result['label'] = value;
            break;
          case 'message':
          case 'tx_description':
            result['message'] = value;
            break;
          case 'tx_payment_id':
            result['tx_payment_id'] = value;
            break;
          default:
            result[lowerKey] = value;
        }
      } else {
        // Include unrecognized parameters as-is.
        result[key] = value;
      }
    }
    return (params: result, amounts: amounts, labels: labels);
  }

  static String? _normalizeAmount(String amount) {
    final trimmed = amount.trim();
    return RegExp(r'^(\d+(\.\d+)?|\.\d+)$').hasMatch(trimmed) ? trimmed : null;
  }

  /// Splits a Monero URI's `;` separated addresses into individual
  /// recipients, each with its amount and name from [amounts] and [labels].
  static List<PaymentUriRecipient> _parseMoneroRecipients({
    required String address,
    required List<String>? amounts,
    required List<String>? labels,
  }) {
    final addresses = address.split(';').map((e) => e.trim()).toList();
    if (addresses.length == 1) {
      if (amounts != null && amounts.length > 1) {
        throw FormatException(
          "Invalid payment URI amount: ${amounts.join(';')}",
        );
      }
      return [
        PaymentUriRecipient(
          address: address,
          amount: amounts?.single,
          label: labels?.join(';'),
        ),
      ];
    }

    if (addresses.contains("")) {
      throw FormatException("Empty address in payment URI: $address");
    }

    if (amounts == null || amounts.length != addresses.length) {
      throw const FormatException(
        "Payment URI must have one amount per recipient",
      );
    }

    if (labels != null && labels.length != addresses.length) {
      throw const FormatException(
        "Payment URI must have one name per recipient",
      );
    }

    return [
      for (int i = 0; i < addresses.length; i++)
        PaymentUriRecipient(
          address: addresses[i],
          amount: amounts[i],
          label: labels?[i].isNotEmpty == true ? labels![i] : null,
        ),
    ];
  }

  /// Whether [input], the new text of an address field whose text was
  /// [previous], may be a payment URI worth parsing: several characters
  /// changed at once, as when pasted, or it contains a scheme separator.
  static bool mayBePaymentUri(String input, String previous) =>
      (input.length - previous.length).abs() > 1 || input.contains(':');

  /// Centralized method to handle various cryptocurrency URIs and return a common object.
  ///
  /// Multi-recipient URIs are only returned when [allowMultipleRecipients] is
  /// true, so callers that handle a single address never drop recipients.
  ///
  /// Returns null on failure to parse
  static PaymentUriData? parsePaymentUri(
    String uri, {
    Logging? logging,
    bool allowMultipleRecipients = false,
  }) {
    // hacky check its not just a bcash, ecash, or xel address
    const cashAddrSchemes = {"bitcoincash", "bchtest", "ecash", "ectest"};
    final parsedUri = Uri.tryParse(uri);
    final scheme = parsedUri?.scheme.toLowerCase();
    if (parsedUri != null &&
        (scheme == "xel" ||
            (!parsedUri.hasQuery && cashAddrSchemes.contains(scheme)))) {
      return null;
    }

    try {
      final parsedUri = _parseUri(uri);
      final Map<String, String> parsedData = parsedUri.params;

      // Normalize the URI scheme.
      final String scheme = parsedData['scheme'] ?? '';
      parsedData.remove('scheme');
      final address = parsedData['address']!.trim();

      // Filter out unrecognized parameters.
      final filteredParams = _filterParams(parsedData);

      final amount = filteredParams['amount'] ?? filteredParams['tx_amount'];
      final label = filteredParams['label'] ?? filteredParams['recipient_name'];

      final List<PaymentUriRecipient> recipients;
      if (scheme == "monero") {
        recipients = _parseMoneroRecipients(
          address: address,
          amounts: parsedUri.amounts,
          labels: parsedUri.labels,
        );
        if (recipients.length > 1 && !allowMultipleRecipients) {
          throw const FormatException(
            "Multiple recipients are not supported here",
          );
        }
      } else {
        recipients = [
          PaymentUriRecipient(
            address: cashAddrSchemes.contains(scheme)
                ? "$scheme:$address".toLowerCase()
                : address,
            amount: amount,
            label: label,
          ),
        ];
      }

      return PaymentUriData(
        scheme: scheme,
        recipients: recipients,
        message: filteredParams['message'] ?? filteredParams['tx_description'],
        paymentId: filteredParams['tx_payment_id'],
        // Specific to Monero
        additionalParams: filteredParams,
      );
    } catch (e, s) {
      logging?.i("Invalid payment URI: $uri", error: e, stackTrace: s);
      return null;
    }
  }

  /// Builds a uri string with the given address and query parameters (if any)
  static String buildUriString(
    String scheme,
    String address,
    Map<String, String> params,
  ) {
    // Filter unrecognized parameters.
    final filteredParams = _filterParams(params);
    String uriString;

    // cashaddrs strike again
    if (address.startsWith("$scheme:")) {
      uriString = address;
    } else {
      uriString = "$scheme:$address";
    }

    if (filteredParams.isNotEmpty) {
      uriString += Uri(queryParameters: filteredParams).toString();
    }

    return uriString;
  }

  static String buildPaymentUriString({
    required String scheme,
    required String address,
    String? amount,
    String? message,
  }) {
    final normalizedScheme = scheme.toLowerCase();
    final usesMoneroParameters =
        normalizedScheme == "monero" || normalizedScheme == "wownero";
    final params = <String, String>{
      if (amount != null && amount.isNotEmpty)
        usesMoneroParameters ? "tx_amount" : "amount": amount,
      if (message != null && message.isNotEmpty)
        usesMoneroParameters ? "tx_description" : "message": message,
    };

    return buildUriString(scheme, address, params);
  }

  /// returns empty if bad data
  static Map<String, dynamic> decodeQRSeedData(String data) {
    Map<String, dynamic> result = {};
    try {
      result = Map<String, dynamic>.from(jsonDecode(data) as Map);
    } catch (e, s) {
      Logging.instance.d(
        "Exception caught in parseQRSeedData($data)",
        error: e,
        stackTrace: s,
      );
    }
    return result;
  }

  /// encode mnemonic words to qrcode formatted string
  static String encodeQRSeedData(List<String> words) {
    return jsonEncode({"mnemonic": words});
  }

  /// Method to get CryptoCurrency based on URI scheme.
  static CryptoCurrency? _getCryptoCurrencyByScheme(String scheme) {
    if (AppConfig.coins.map((e) => e.uriScheme).toSet().contains(scheme)) {
      return AppConfig.coins.firstWhere((e) => e.uriScheme == scheme);
    } else {
      return null;
      // throw UnsupportedError('Unsupported URI scheme: $scheme');
    }
  }

  /// Formats an address string to remove any unnecessary prefixes or suffixes.
  String formatEpicCashAddress(String epicAddress) {
    // strip http:// or https:// prefixes if the address contains an @ symbol (and is thus an epicbox address)
    if ((epicAddress.startsWith("http://") ||
            epicAddress.startsWith("https://")) &&
        epicAddress.contains("@")) {
      epicAddress = epicAddress.replaceAll("http://", "");
      epicAddress = epicAddress.replaceAll("https://", "");
    }
    // strip mailto: prefix
    if (epicAddress.startsWith("mailto:")) {
      epicAddress = epicAddress.replaceAll("mailto:", "");
    }
    // strip / suffix if the address contains an @ symbol (and is thus an epicbox address)
    if (epicAddress.endsWith("/") && epicAddress.contains("@")) {
      epicAddress = epicAddress.substring(0, epicAddress.length - 1);
    }
    return epicAddress;
  }

  /// Formats an address string to remove any unnecessary prefixes or suffixes.
  String formatAddressMwc(String mimblewimblecoinAddress) {
    // strip http:// or https:// prefixes if the address contains an @ symbol (and is thus an mwcmqs address)
    if ((mimblewimblecoinAddress.startsWith("http://") ||
            mimblewimblecoinAddress.startsWith("https://")) &&
        mimblewimblecoinAddress.contains("@")) {
      mimblewimblecoinAddress = mimblewimblecoinAddress.replaceAll(
        "http://",
        "",
      );
      mimblewimblecoinAddress = mimblewimblecoinAddress.replaceAll(
        "https://",
        "",
      );
    }
    // strip mailto: prefix
    if (mimblewimblecoinAddress.startsWith("mailto:")) {
      mimblewimblecoinAddress = mimblewimblecoinAddress.replaceAll(
        "mailto:",
        "",
      );
    }
    // strip / suffix if the address contains an @ symbol (and is thus an mwcmqs address)
    if (mimblewimblecoinAddress.endsWith("/") &&
        mimblewimblecoinAddress.contains("@")) {
      mimblewimblecoinAddress = mimblewimblecoinAddress.substring(
        0,
        mimblewimblecoinAddress.length - 1,
      );
    }
    return mimblewimblecoinAddress;
  }

  /// Formats OP_RETURN hex data for display in tooltip.
  /// If data matches Rosen Bridge format, shows structured fields.
  /// Otherwise returns the raw hex with a generic description.
  static String formatOpReturnTooltip(String hex) {
    // Rosen Bridge OP_RETURN format:
    // toChain(1B) + bridgeFee(8B) + networkFee(8B) + addrLen(1B) + toAddress(var)
    const minRosenLen = 36; // minimum 18 bytes
    if (hex.length < minRosenLen) {
      return "Raw OP_RETURN data:\n$hex";
    }

    try {
      // Must match @rosen-bridge/rosen-extractor SUPPORTED_CHAINS order.
      const chains = [
        'ergo',
        'cardano',
        'bitcoin',
        'ethereum',
        'binance',
        'base',
        'doge',
        'bitcoin-runes',
        'firo',
        'handshake',
      ];

      final toChainCode = int.parse(hex.substring(0, 2), radix: 16);
      if (toChainCode >= chains.length) {
        return "Raw OP_RETURN data:\n$hex";
      }

      final bridgeFee = BigInt.parse(
        hex.substring(2, 18),
        radix: 16,
      ).toString();
      final networkFee = BigInt.parse(
        hex.substring(18, 34),
        radix: 16,
      ).toString();
      final addrLen = int.parse(hex.substring(34, 36), radix: 16);
      final addrEnd = 36 + addrLen * 2;
      if (hex.length < addrEnd) {
        return "Raw OP_RETURN data:\n$hex";
      }
      final toAddressHex = hex.substring(36, addrEnd);

      return "Rosen Bridge data\n"
          "  To chain: ${chains[toChainCode]}\n"
          "  Bridge fee: $bridgeFee\n"
          "  Network fee: $networkFee\n"
          "  To address (hex): $toAddressHex";
    } catch (_) {
      return "Raw OP_RETURN data:\n$hex";
    }
  }

  static int opReturnOutputVSizeFromHex(String hex) {
    if (hex.length.isOdd || !RegExp(r'^[0-9a-fA-F]*$').hasMatch(hex)) {
      throw const FormatException("Invalid OP_RETURN hex");
    }

    final dataBytes = hex.length ~/ 2;
    if (dataBytes > 80) {
      throw FormatException(
        "OP_RETURN data exceeds 80 byte limit: $dataBytes bytes",
      );
    }

    final pushPrefixBytes = dataBytes <= 75 ? 1 : 2;
    final scriptBytes = 1 + pushPrefixBytes + dataBytes;

    // value(8) + compact script length(1, since max script is 83 bytes) + script
    return 8 + 1 + scriptBytes;
  }
}

class PaymentUriRecipient {
  final String address;
  final String? amount;
  final String? label;

  const PaymentUriRecipient({required this.address, this.amount, this.label});

  @override
  String toString() =>
      "PaymentUriRecipient { "
      "address: $address, "
      "amount: $amount, "
      "label: $label"
      " }";
}

class PaymentUriData {
  final String? scheme;

  /// Always contains at least one recipient.
  final List<PaymentUriRecipient> recipients;
  final String? message;
  final String? paymentId; // Specific to Monero.
  final Map<String, String> additionalParams;

  String get address => recipients.first.address;
  String? get amount => recipients.first.amount;
  String? get label => recipients.first.label;

  bool get isMultiRecipient => recipients.length > 1;

  CryptoCurrency? get coin => AddressUtils._getCryptoCurrencyByScheme(
    scheme ?? "", // empty will just return null
  );

  String? get memo {
    for (final value in [
      paymentId,
      additionalParams["memo"],
      additionalParams["dt"],
      additionalParams["destination_tag"],
    ]) {
      if (value?.isNotEmpty == true) {
        return value;
      }
    }
    return null;
  }

  PaymentUriData({
    required this.recipients,
    this.scheme,
    this.message,
    this.paymentId,
    required this.additionalParams,
  });

  @override
  String toString() =>
      "PaymentUriData { "
      "coin: $coin, "
      "recipients: $recipients, "
      "scheme: $scheme, "
      "message: $message, "
      "paymentId: $paymentId, "
      "additionalParams: $additionalParams"
      " }";
}
